struct ColorState: Equatable { var selectedID: Int? }
enum ColorAction { case selected(Int), cleared }
func colorReduce(_ state: ColorState, _ action: ColorAction) -> ColorState {
    var next = state
    switch action {
    case let .selected(id): next.selectedID = id
    case .cleared: next.selectedID = nil
    }
    return next
}
let original = ColorState(selectedID: 4)
let replay = [.selected(5), .cleared] as [ColorAction]
let result = replay.reduce(original, colorReduce)
print(original.selectedID ?? -1)
print(result.selectedID ?? -1)

