struct AssemblyState: Equatable {
    var step = StepState()
    var details = false
}
enum AssemblyAction { case step(StepAction), toggleDetails }
func assemblyReduce(
    _ state: AssemblyState, _ action: AssemblyAction
) -> AssemblyState {
    var next = state
    switch action {
    case let .step(action): next.step = stepReduce(state.step, action)
    case .toggleDetails: next.details.toggle()
    }
    return next
}
